declare(strict_types=1);use ImAuthenticator\Security;use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$admin=$auth->requireAdmin();$run=null;if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);$run=$toolkit->runDiagnostics((int)$_POST['application_id'],(int)$admin['id']);}$options='';foreach($db->all('SELECT id,name FROM applications WHERE deleted_at IS NULL ORDER BY name') as $a)$options.='<option value="'.(int)$a['id'].'">'.Web::e($a['name']).'</option>';$templates='';foreach($toolkit->templates() as $t)$templates.='<tr><td>'.Web::e($t['name']).'</td><td>'.Web::e($t['app_type']).'</td><td>'.Web::e($t['integration_type']).'</td></tr>';$diag=$run?'<pre class="code">'.Web::e(json_encode($db->all('SELECT * FROM integration_diagnostic_checks WHERE run_id=?',[$run]),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</pre>':'';Web::page('Integration tools','<div class="page-head"><div><h1>Integration diagnostics / templates</h1><p>Presety, diagnostyka i generatory konfiguracji.</p></div></div><section class="card"><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><label>Aplikacja<select name="application_id">'.$options.'</select></label><button class="primary">Uruchom diagnostykę</button></form>'.$diag.'</section><div class="table-wrap"><table><thead><tr><th>Szablon</th><th>Typ</th><th>Integracja</th></tr></thead><tbody>'.$templates.'</tbody></table></div>',$admin);
